import { Entity, SkinnedMesh, StandardMaterial, Animator, loadGLTF, quat } from "../engine/index.js";
import { FLAG } from "./protocol.js";

/**
 * TIDEFALL: players as skinned characters (adapted from BREACH's characters.js). The raider and its clips
 * are generated by tools/make-models.mjs and read with the engine's glTF loader. Everyone shares one
 * skeleton, one geometry and one material; each has an Animator and a six-colour palette (shirt in the
 * team colour, a skin tone picked from the player id).
 *
 * A Raider is driven by what the client knows about a player this frame: where they are, how fast they
 * move, whether they swim, wade, hang on the grapple or stagger. From that it picks a clip. A shove plays
 * once over whatever else was playing.
 * @module game/characters
 */

let assets = null;
/** Load the model once. */
export async function loadCharacters(base = "assets/models/") {
    if (assets) return assets;
    const asset = await loadGLTF(base + "raider.glb");
    assets = { asset, geometry: asset.geometry("body"), upright: asset.upright };
    return assets;
}
export const charactersReady = () => !!assets;

const SKINS = [[0.93, 0.72, 0.56], [0.78, 0.55, 0.38], [0.55, 0.36, 0.24], [0.36, 0.23, 0.16], [0.97, 0.8, 0.66]];
/** shorts, straw, leather, rope: the same for everyone */
const FIXED = [[0.82, 0.76, 0.6], [0.92, 0.8, 0.5], [0.42, 0.26, 0.14], [0.85, 0.78, 0.6]];
let shared = null;
const material = () => shared || (shared = new StandardMaterial({ palette: new Float32Array(StandardMaterial.PALETTE_SIZE * 3).fill(1), specular: 0.2, shininess: 18 }));

export class Raider {
    /** @param {number[]} color team colour @param {number} id player id, for the skin tone */
    constructor(color, id) {
        const a = assets;
        this.animator = new Animator(a.asset.skeleton, a.asset.clips);
        /** place and turn this; +Y of the model is forward */
        this.root = new Entity({ name: "raider" });
        this.root.interpolate = false;
        const mesh = new SkinnedMesh(a.geometry, material(), this.animator);
        this.palette = new Float32Array(StandardMaterial.PALETTE_SIZE * 3);
        this.palette.set(SKINS[id % SKINS.length], 3);
        this.palette.set(FIXED[0], 6); this.palette.set(FIXED[1], 9); this.palette.set(FIXED[2], 12); this.palette.set(FIXED[3], 15);
        this.emissive = new Float32Array(3);
        mesh.uniforms = { u_palette: this.palette, u_emissive: this.emissive };
        this.setColor(color);
        this.body = this.root.add(new Entity({ name: "body", mesh, cullRadius: 1.5 }));
        this.body.interpolate = false;
        quat.copy(this.body.rotation, a.upright);
        this.stride = 0;
        this.shoving = 0;
        this.animator.play("idle", { fade: 0 });
    }

    setColor(c) { this.palette.set(c, 0); }

    /** Play the shove once (the wind-up shows before the server's answer arrives). */
    shove() { this.shoving = 0.45; this.animator.play("shove", { fade: 0.05, loop: false }); }

    /**
     * @param {number} dt
     * @param {{ x: number, y: number, z: number, face: number, flags: number, speed: number, vz: number, wade?: boolean }} s
     * @returns {boolean} true on a frame a foot comes down (for the footstep sound)
     */
    update(dt, s) {
        const f = s.flags, an = this.animator, alive = (f & FLAG.alive) !== 0;
        this.root.visible = alive;
        this.root.setPosition(s.x, s.y, s.z);
        this.root.setYaw(s.face - Math.PI / 2);
        let step = false;
        if (this.shoving > 0) this.shoving -= dt;
        else if (f & FLAG.stun) an.play("stagger", { fade: 0.08 });
        else if (f & FLAG.hook) an.play("hook", { fade: 0.08 });
        else if (f & FLAG.swim) an.play(s.speed > 0.5 ? "swim" : "tread", { fade: 0.25, speed: s.speed > 0.5 ? Math.max(0.6, s.speed / 2.6) : 1 });
        else if (!(f & FLAG.ground)) an.play(s.vz > 0 ? "jump" : "fall", { fade: 0.15 });
        else if (s.wade || (f & FLAG.sunk)) an.play(s.speed > 0.3 ? "wade" : "idle", { fade: 0.2, speed: Math.max(0.5, s.speed / 3) });
        else if (s.speed > 4.6) an.play("run", { fade: 0.15, speed: s.speed / 8 });
        else if (s.speed > 0.5) an.play("walk", { fade: 0.15, speed: s.speed / 3.4 });
        else an.play("idle", { fade: 0.25 });
        if ((f & FLAG.ground) && !(f & FLAG.swim) && s.speed > 0.5) { this.stride += s.speed * dt; if (this.stride > 1.9) { this.stride = 0; step = true; } }
        an.sample(dt);
        an.solve();
        // an idol carrier glows faintly, so everyone can see who has one
        const e = this.emissive, glow = f & FLAG.idol ? 0.25 + 0.15 * Math.sin(performance.now() / 160) : 0;
        e[0] = glow * 1.6; e[1] = glow * 0.5; e[2] = glow * 1.4;
        return step;
    }
}
